/**
 * Where the strip may stay up by default. The landscape cluster keeps a header
 * band free for it on every screen, so there it covers nothing and can stay
 * like a real cluster's lamps; on the round glass it sits over content, so
 * there it folds away after a peek.
 */
static constexpr bool kStripAlwaysDefault = LCD_WIDTH != LCD_HEIGHT;

